<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/api.php';cmsApiBootstrap();require_once __DIR__.'/../../includes/helpers.php';require_once __DIR__.'/../../includes/module-registry.php';$pdo=cmsPdo();if(!cmsModuleEnabled($pdo,'catalog'))cmsJson(['ok'=>false,'error'=>'MODULE_DISABLED'],404);$type=$_GET['type']??'all';
if($type==='brands'){$rows=$pdo->query('SELECT id,slug,name_ar,name_en,description_ar,description_en,logo_path,sort_order FROM catalog_brands WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();cmsJson(['ok'=>true,'data'=>$rows]);}
if($type==='categories'){$rows=$pdo->query('SELECT id,slug,name_ar,name_en,sort_order FROM catalog_categories WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();cmsJson(['ok'=>true,'data'=>$rows]);}
$where='p.deleted_at IS NULL AND p.is_active=1';$params=[];if(!empty($_GET['slug'])){$where.=' AND p.slug=:slug';$params[':slug']=cmsSlug(cmsStr($_GET['slug'],190));}if(!empty($_GET['brand'])){$where.=' AND b.slug=:brand';$params[':brand']=cmsSlug(cmsStr($_GET['brand'],190));}if(!empty($_GET['category'])){$where.=' AND c.slug=:cat';$params[':cat']=cmsSlug(cmsStr($_GET['category'],190));}if(!empty($_GET['featured']))$where.=' AND p.is_featured=1';$sql='SELECT p.id,p.slug,p.name_ar,p.name_en,p.description_ar,p.description_en,p.image_path,p.sku,p.price,p.currency,p.availability,p.is_featured,p.is_new,p.sort_order,b.id brand_id,b.slug brand_slug,b.name_ar brand_name_ar,b.name_en brand_name_en,c.id category_id,c.slug category_slug,c.name_ar category_name_ar,c.name_en category_name_en FROM catalog_products p LEFT JOIN catalog_brands b ON b.id=p.brand_id LEFT JOIN catalog_categories c ON c.id=p.category_id WHERE '.$where.' ORDER BY p.is_featured DESC,p.sort_order,p.id';$s=$pdo->prepare($sql);$s->execute($params);$products=$s->fetchAll();if($type==='products'||!empty($_GET['slug']))cmsJson(['ok'=>true,'data'=>$products]);$brands=$pdo->query('SELECT id,slug,name_ar,name_en,description_ar,description_en,logo_path,sort_order FROM catalog_brands WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();$categories=$pdo->query('SELECT id,slug,name_ar,name_en,sort_order FROM catalog_categories WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();cmsJson(['ok'=>true,'data'=>['brands'=>$brands,'categories'=>$categories,'products'=>$products]]);
